// PharmaDesk — your vendor dashboard backend (free Cloudflare Worker).
// Setup once in the Cloudflare website (no terminal):
//   1. Workers & Pages → Create → Worker → name it "pharmadesk-admin" → Deploy → Edit code → paste this file → Deploy.
//   2. Storage → KV → Create namespace "pharmadesk-shops". In the Worker: Settings → Bindings → KV → variable name SHOPS.
//   3. Worker → Settings → Variables and secrets: add PUBLIC_KEY (your licence public key) and ADMIN_TOKEN (a long password; Secret).
// Then open the Worker's address in any browser — your PharmaDesk Vendor app (keys + shops) opens there.
// Shops send a small check-in (licence, shop name, counts — never patient data). You see them in the PharmaDesk Vendor app.
export default {
  async fetch(req, env) {
    const url = new URL(req.url);
    const cors = { 'access-control-allow-origin': '*', 'access-control-allow-headers': 'authorization, content-type', 'access-control-allow-methods': 'GET, POST, OPTIONS' };
    const json = (o, s = 200) => new Response(JSON.stringify(o), { status: s, headers: { ...cors, 'content-type': 'application/json' } });
    if (req.method === 'OPTIONS') return new Response(null, { status: 204, headers: cors });
    // Your dashboard app (keys + shops). The page itself holds no secrets; the shop list needs your admin password.
    if (req.method === 'GET' && url.pathname === '/manifest.webmanifest') return new Response(MANIFEST, { headers: { 'content-type': 'application/manifest+json' } });
    if (req.method === 'GET' && url.pathname === '/sw.js') return new Response(SW, { headers: { 'content-type': 'text/javascript', 'cache-control': 'no-store' } });
    if (req.method === 'GET' && ICONS[url.pathname]) return new Response(Uint8Array.from(atob(ICONS[url.pathname]), c => c.charCodeAt(0)), { headers: { 'content-type': 'image/png', 'cache-control': 'public, max-age=86400' } });
    if (req.method === 'GET' && (url.pathname === '/' || url.pathname === '/index.html'))
      return new Response(ADMIN_HTML, { headers: { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store', 'x-frame-options': 'DENY', 'referrer-policy': 'no-referrer' } });
    try {
      if (url.pathname === '/checkin' && req.method === 'POST') {
        const b = await req.json();
        const lic = await verifyLicense(String(b.license || ''), env.PUBLIC_KEY);
        if (!lic) return json({ error: 'Licence not valid' }, 403);
        const id = String(b.installId || '').replace(/[^\w-]/g, '').slice(0, 40);
        if (!id) return json({ error: 'Missing install id' }, 400);
        const key = 'shop:' + id;
        const prev = JSON.parse((await env.SHOPS.get(key)) || '{}');
        const now = new Date().toISOString();
        const rec = {
          ...prev, installId: id, licenseId: lic.id, licensedTo: lic.shop, plan: lic.plan || 'standard', expires: lic.expires || null,
          shop: String(b.shop || '').slice(0, 80), city: String(b.city || '').slice(0, 60), phone: String(b.phone || '').slice(0, 30),
          version: String(b.version || '').slice(0, 20), platform: String(b.platform || '').slice(0, 20),
          stats: sanitizeStats(b.stats), support: b.support && typeof b.support === 'object' ? b.support : null,
          lastSeen: now, firstSeen: prev.firstSeen || now, suspended: !!prev.suspended, note: prev.note || '',
        };
        await env.SHOPS.put(key, JSON.stringify(rec));
        return json({ suspended: rec.suspended, message: rec.suspended ? (rec.note || 'Your plan is paused. Please contact the vendor.') : null });
      }
      if (!env.ADMIN_TOKEN || (req.headers.get('authorization') || '') !== 'Bearer ' + env.ADMIN_TOKEN) return json({ error: 'Wrong admin password' }, 401);
      if (url.pathname === '/shops' && req.method === 'GET') {
        const shops = []; let cursor;
        do {
          const l = await env.SHOPS.list({ prefix: 'shop:', cursor });
          for (const k of l.keys) { const v = await env.SHOPS.get(k.name); if (v) shops.push(JSON.parse(v)); }
          cursor = l.list_complete ? null : l.cursor;
        } while (cursor);
        return json({ shops });
      }
      const m = url.pathname.match(/^\/shops\/([\w-]+)\/(suspend|forget)$/);
      if (m && req.method === 'POST') {
        const key = 'shop:' + m[1];
        const rec = JSON.parse((await env.SHOPS.get(key)) || 'null');
        if (!rec) return json({ error: 'Shop not found' }, 404);
        if (m[2] === 'forget') { await env.SHOPS.delete(key); return json({ ok: true }); }
        const b = await req.json().catch(() => ({}));
        rec.suspended = !!b.on; rec.note = String(b.note || '').slice(0, 200);
        await env.SHOPS.put(key, JSON.stringify(rec));
        return json({ ok: true, shop: rec });
      }
      return json({ error: 'Not found' }, 404);
    } catch (e) { return json({ error: String(e && e.message || e) }, 500); }
  },
};

function sanitizeStats(s) {
  const o = {}; if (!s || typeof s !== 'object') return o;
  for (const k of ['bills7d', 'sales7d', 'medicines', 'users', 'devices', 'patients']) if (Number.isFinite(Number(s[k]))) o[k] = Number(s[k]);
  return o;
}
const b64 = s => { s = s.replace(/-/g, '+').replace(/_/g, '/'); s += '==='.slice((s.length + 3) % 4); return Uint8Array.from(atob(s), c => c.charCodeAt(0)); };
async function verifyLicense(token, pub) {
  if (!token || !pub) return null;
  const p = token.trim().split('.');
  if (p.length !== 3 || p[0] !== 'PD1') return null;
  try {
    const key = await crypto.subtle.importKey('raw', b64(pub), { name: 'Ed25519' }, false, ['verify']);
    if (!(await crypto.subtle.verify({ name: 'Ed25519' }, key, b64(p[2]), new TextEncoder().encode(p[1])))) return null;
    return JSON.parse(new TextDecoder().decode(b64(p[1])));
  } catch { return null; }
}

// ADMIN_PAGE — generated from admin.html by build-worker.mjs. Do not edit by hand.
const ADMIN_HTML = "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><link rel=\"manifest\" href=\"/manifest.webmanifest\"><link rel=\"icon\" href=\"/icon-192.png\"><link rel=\"apple-touch-icon\" href=\"/icon-192.png\"><meta name=\"theme-color\" content=\"#0E8F7E\"><meta name=\"apple-mobile-web-app-capable\" content=\"yes\"><meta name=\"apple-mobile-web-app-title\" content=\"PD Vendor\"><script>window.PD_WORKER=true;if(\"serviceWorker\" in navigator)navigator.serviceWorker.register(\"/sw.js\").catch(()=>{})</script></head><body><title>PharmaDesk Vendor</title>\n<meta name=\"claude:viewport-fit-sides\" content=\"cover\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Figtree:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600&display=swap\">\n<style>\n/* Layout: one working column — header, tab bar, then the active panel. Cards only for shops and the key result. */\n:root {\n  --bg: #EEF3F2; --surface: #FFFFFF; --sunk: #F5F8F7; --line: #D8E2E0; --text: #0E1B1A; --muted: #5B6B69;\n  --accent: #0E8F7E; --accent-ink: #FFFFFF; --accent-soft: #D7F0EB;\n  --good: #1B8A4B; --good-soft: #DDF3E5; --warn: #A86500; --warn-soft: #FBEBD0; --bad: #B4232F; --bad-soft: #F9DDE0;\n  --display: \"Figtree\", \"Segoe UI\", system-ui, sans-serif; --body: \"Figtree\", \"Segoe UI\", system-ui, sans-serif;\n  --mono: \"JetBrains Mono\", ui-monospace, \"SF Mono\", Menlo, Consolas, monospace;\n  --r: 12px;\n}\n@media (prefers-color-scheme: dark) { :root:not([data-theme=\"light\"]) {\n  --bg: #0A1413; --surface: #11201E; --sunk: #0D1A18; --line: #22332F; --text: #E6F0EE; --muted: #93A6A2;\n  --accent: #2CC3AC; --accent-ink: #04211C; --accent-soft: #123C35;\n  --good: #4FD089; --good-soft: #12301F; --warn: #F0B356; --warn-soft: #33260F; --bad: #F2737D; --bad-soft: #3A1519; color-scheme: dark; } }\n:root[data-theme=\"dark\"] {\n  --bg: #0A1413; --surface: #11201E; --sunk: #0D1A18; --line: #22332F; --text: #E6F0EE; --muted: #93A6A2;\n  --accent: #2CC3AC; --accent-ink: #04211C; --accent-soft: #123C35;\n  --good: #4FD089; --good-soft: #12301F; --warn: #F0B356; --warn-soft: #33260F; --bad: #F2737D; --bad-soft: #3A1519; color-scheme: dark; }\n* { box-sizing: border-box; }\n[hidden] { display: none !important; }\nbody { background: var(--bg); color: var(--text); font-family: var(--body); font-size: 15px; line-height: 1.5; margin: 0; }\n.wrap { max-width: 1080px; margin: 0 auto; padding-block: 20px 60px; padding-left: max(16px, env(safe-area-inset-left, 0px)); padding-right: max(16px, env(safe-area-inset-right, 0px)); display: flex; flex-direction: column; gap: 18px; }\nheader { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }\n.mark { width: 40px; height: 40px; border-radius: 11px; background: var(--accent); color: var(--accent-ink); display: grid; place-items: center; font-weight: 800; font-size: 15px; letter-spacing: .02em; }\nh1 { font-family: var(--display); font-size: 21px; margin: 0; letter-spacing: -.01em; }\n.sub { color: var(--muted); font-size: 13px; }\nh2 { font-family: var(--display); font-size: 17px; margin: 0; text-wrap: balance; }\n.tabs { display: flex; gap: 4px; background: var(--sunk); border: 1px solid var(--line); padding: 4px; border-radius: 12px; width: fit-content; max-width: 100%; overflow-x: auto; }\n.tab { border: 0; background: transparent; color: var(--muted); font: 600 14px var(--body); padding: 8px 16px; border-radius: 9px; cursor: pointer; white-space: nowrap; }\n.tab[aria-selected=\"true\"] { background: var(--surface); color: var(--text); box-shadow: 0 1px 2px rgba(0,0,0,.08); }\n.panel { display: flex; flex-direction: column; gap: 16px; }\n.box { background: var(--surface); border: 1px solid var(--line); border-radius: var(--r); padding: 18px; display: flex; flex-direction: column; gap: 14px; min-width: 0; }\n.grid { display: grid; gap: 12px; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); }\nlabel.f { display: flex; flex-direction: column; gap: 5px; font-size: 13px; font-weight: 600; color: var(--muted); min-width: 0; }\ninput, select, textarea { font: 500 15px var(--body); color: var(--text); background: var(--sunk); border: 1px solid var(--line); border-radius: 10px; padding: 10px 12px; width: 100%; min-width: 0; }\ntextarea { font-family: var(--mono); font-size: 12px; min-height: 90px; resize: vertical; }\ninput:focus-visible, select:focus-visible, textarea:focus-visible, button:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }\n.row { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; }\n.spacer { flex: 1; }\n.btn { font: 700 14px var(--body); border-radius: 10px; padding: 10px 16px; border: 1px solid var(--line); background: var(--surface); color: var(--text); cursor: pointer; }\n.btn:hover { border-color: var(--accent); }\n.btn.primary { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }\n.btn.danger { color: var(--bad); }\n.btn.danger.solid { background: var(--bad); color: #fff; border-color: var(--bad); }\n.btn.sm { padding: 6px 11px; font-size: 13px; }\n.btn:disabled { opacity: .5; cursor: default; }\n.key { font-family: var(--mono); font-size: 12.5px; word-break: break-all; background: var(--sunk); border: 1px dashed var(--line); border-radius: 10px; padding: 12px; user-select: all; }\n.note { font-size: 13px; color: var(--muted); margin: 0; max-width: 70ch; }\n.callout { border-radius: 10px; padding: 12px 14px; font-size: 14px; }\n.callout.warn { background: var(--warn-soft); color: var(--text); border: 1px solid color-mix(in srgb, var(--warn) 35%, transparent); }\n.callout.good { background: var(--good-soft); border: 1px solid color-mix(in srgb, var(--good) 35%, transparent); }\n.callout.bad { background: var(--bad-soft); border: 1px solid color-mix(in srgb, var(--bad) 35%, transparent); }\n.tiles { display: grid; gap: 12px; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); }\n.tile { background: var(--surface); border: 1px solid var(--line); border-radius: var(--r); padding: 14px 16px; }\n.tile b { display: block; font-size: 26px; font-variant-numeric: tabular-nums; font-family: var(--display); }\n.tile span { font-size: 12px; color: var(--muted); text-transform: uppercase; letter-spacing: .06em; font-weight: 700; }\n.shops { display: grid; gap: 12px; grid-template-columns: repeat(auto-fill, minmax(min(100%, 330px), 1fr)); }\n.shop { background: var(--surface); border: 1px solid var(--line); border-radius: var(--r); padding: 16px; display: flex; flex-direction: column; gap: 10px; min-width: 0; border-top: 4px solid var(--good); }\n.shop.paused { border-top-color: var(--bad); } .shop.stale { border-top-color: var(--warn); }\n.shop h3 { margin: 0; font-size: 16px; overflow-wrap: anywhere; }\n.pill { display: inline-flex; align-items: center; gap: 5px; font-size: 12px; font-weight: 700; border-radius: 99px; padding: 3px 9px; white-space: nowrap; }\n.pill.good { background: var(--good-soft); color: var(--good); } .pill.warn { background: var(--warn-soft); color: var(--warn); } .pill.bad { background: var(--bad-soft); color: var(--bad); } .pill.plain { background: var(--sunk); color: var(--muted); }\ndl { display: grid; grid-template-columns: auto 1fr; gap: 3px 12px; margin: 0; font-size: 13px; }\ndt { color: var(--muted); } dd { margin: 0; font-variant-numeric: tabular-nums; overflow-wrap: anywhere; }\n.stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; }\n.stat { background: var(--sunk); border-radius: 8px; padding: 6px 8px; font-size: 11px; color: var(--muted); }\n.stat b { display: block; font-size: 15px; color: var(--text); font-variant-numeric: tabular-nums; }\n.support { background: var(--accent-soft); border-radius: 10px; padding: 10px 12px; font-size: 13px; display: flex; flex-direction: column; gap: 4px; }\n.mono { font-family: var(--mono); font-size: 12.5px; }\ntable { width: 100%; border-collapse: collapse; font-size: 13px; }\nth, td { text-align: left; padding: 8px 10px; border-bottom: 1px solid var(--line); vertical-align: top; }\nth { color: var(--muted); font-size: 12px; text-transform: uppercase; letter-spacing: .05em; }\n.tw { overflow-x: auto; }\n.toast { position: fixed; left: 50%; transform: translateX(-50%); bottom: calc(18px + env(safe-area-inset-bottom, 0px)); background: var(--text); color: var(--bg); padding: 10px 16px; border-radius: 10px; font-weight: 600; font-size: 14px; z-index: 20; }\n.example { font-size: 12px; font-weight: 700; color: var(--warn); text-transform: uppercase; letter-spacing: .06em; }\n@media (prefers-reduced-motion: no-preference) { .shop, .box { animation: in .25s ease both; } @keyframes in { from { opacity: .4; transform: translateY(4px); } } }\n</style>\n\n<div class=\"wrap\">\n  <header>\n    <div class=\"mark\" aria-hidden=\"true\">PD</div>\n    <div><h1>PharmaDesk Vendor</h1><div class=\"sub\">Licence keys and shops · Awais Amin</div></div>\n  </header>\n\n  <nav class=\"tabs\" role=\"tablist\">\n    <button class=\"tab\" role=\"tab\" id=\"t-keys\" aria-selected=\"true\" data-tab=\"keys\">Make a key</button>\n    <button class=\"tab\" role=\"tab\" id=\"t-shops\" aria-selected=\"false\" data-tab=\"shops\">Shops</button>\n    <button class=\"tab\" role=\"tab\" id=\"t-setup\" aria-selected=\"false\" data-tab=\"setup\">Setup &amp; backup</button>\n  </nav>\n\n  <!-- KEYS -->\n  <section class=\"panel\" id=\"p-keys\">\n    <div class=\"callout warn\" id=\"nokey\" hidden>No signing key on this device yet. Open <b>Setup &amp; backup</b> to create one, or restore your backup.</div>\n    <form class=\"box\" id=\"issue\">\n      <h2>New licence key</h2>\n      <div class=\"grid\">\n        <label class=\"f\">Pharmacy name<input id=\"i-shop\" required maxlength=\"80\" placeholder=\"Al-Shifa Pharmacy\"></label>\n        <label class=\"f\">Plan<select id=\"i-plan\"><option value=\"standard\">Standard</option><option value=\"trial\">Trial</option><option value=\"premium\">Premium</option></select></label>\n        <label class=\"f\">Valid for<select id=\"i-days\"><option value=\"14\">14 days (trial)</option><option value=\"30\">1 month</option><option value=\"90\">3 months</option><option value=\"180\">6 months</option><option value=\"365\" selected>1 year</option><option value=\"730\">2 years</option><option value=\"0\">Never expires</option></select></label>\n      </div>\n      <details><summary class=\"note\" style=\"cursor:pointer\">Lock to one PC (optional)</summary>\n        <label class=\"f\" style=\"margin-top:8px\">PC code shown on the shop's licence screen<input id=\"i-machine\" maxlength=\"80\" placeholder=\"Leave empty to allow any PC\"></label>\n      </details>\n      <div class=\"row\"><button class=\"btn primary\" id=\"b-issue\">Make key</button><span class=\"note\" id=\"i-exp\"></span></div>\n    </form>\n    <div class=\"box\" id=\"result\" hidden>\n      <div class=\"row\"><h2 id=\"r-title\">Key ready</h2><span class=\"spacer\"></span><button class=\"btn primary sm\" id=\"b-copykey\" type=\"button\">Copy key</button></div>\n      <div class=\"key\" id=\"r-key\"></div>\n      <p class=\"note\">Send this key to the pharmacy. They paste it on the licence screen the first time PharmaDesk opens.</p>\n    </div>\n    <div class=\"box\">\n      <div class=\"row\"><h2>Keys made on this device</h2><span class=\"spacer\"></span><input id=\"h-q\" placeholder=\"Search\" style=\"max-width:220px\"></div>\n      <div class=\"tw\"><table><thead><tr><th>Pharmacy</th><th>Plan</th><th>Made</th><th>Expires</th><th></th></tr></thead><tbody id=\"hist\"></tbody></table></div>\n      <p class=\"note\" id=\"h-empty\">Keys you make appear here so you can copy them again.</p>\n    </div>\n  </section>\n\n  <!-- SHOPS -->\n  <section class=\"panel\" id=\"p-shops\" hidden>\n    <form class=\"box\" id=\"conn\">\n      <h2>Your dashboard</h2>\n      <div class=\"grid\">\n        <label class=\"f\" id=\"l-api\">Dashboard address<input id=\"c-api\" placeholder=\"https://pharmadesk-admin.yourname.workers.dev\" inputmode=\"url\"></label>\n        <label class=\"f\">Admin password<input id=\"c-tok\" type=\"password\" autocomplete=\"current-password\"></label>\n      </div>\n      <div class=\"row\"><button class=\"btn primary\">Show shops</button><span class=\"note\" id=\"c-msg\"></span></div>\n    </form>\n    <div class=\"tiles\" id=\"tiles\"></div>\n    <div class=\"row\"><input id=\"s-q\" placeholder=\"Search pharmacy, city or phone\" style=\"max-width:340px\"><select id=\"s-f\" style=\"max-width:200px\"><option value=\"all\">All shops</option><option value=\"active\">Active</option><option value=\"paused\">Paused</option><option value=\"expiring\">Expiring in 30 days</option><option value=\"stale\">Not seen for 3 days</option><option value=\"support\">Support access ON</option></select><span class=\"spacer\"></span><span class=\"example\" id=\"s-ex\" hidden>Example shops — connect to see yours</span></div>\n    <div class=\"shops\" id=\"shops\"></div>\n  </section>\n\n  <!-- SETUP -->\n  <section class=\"panel\" id=\"p-setup\" hidden>\n    <div class=\"box\">\n      <h2>Your signing key</h2>\n      <p class=\"note\">Only this key can make licence keys that PharmaDesk accepts. It stays in this browser. Keep a backup somewhere safe — if it is lost, you cannot make keys for old shops' renewals with the same key.</p>\n      <div id=\"k-none\"><button class=\"btn primary\" id=\"b-gen\" type=\"button\">Create my signing key</button></div>\n      <div id=\"k-have\" hidden class=\"panel\">\n        <label class=\"f\">Public key — send this to your developer to switch licensing on<div class=\"row\"><div class=\"key\" id=\"k-pub\" style=\"flex:1\"></div><button class=\"btn sm\" type=\"button\" id=\"b-copypub\">Copy</button></div></label>\n        <span class=\"note\" id=\"k-made\"></span>\n      </div>\n    </div>\n    <div class=\"box\">\n      <h2>Backup</h2>\n      <p class=\"note\">Copy the backup text and keep it in your email drafts or a password manager. Anyone with it can make keys, so never share it.</p>\n      <div class=\"row\"><button class=\"btn\" type=\"button\" id=\"b-backup\">Copy backup text</button><span class=\"note\" id=\"b-msg\"></span></div>\n      <label class=\"f\">Restore from backup<textarea id=\"r-text\" placeholder='Paste your backup text here ( {\"publicKey\": … } )'></textarea></label>\n      <div class=\"row\"><button class=\"btn\" type=\"button\" id=\"b-restore\">Restore</button><label class=\"btn\" for=\"r-file\" style=\"display:inline-block\">Choose backup file</label><input type=\"file\" id=\"r-file\" accept=\".json,.txt,application/json,text/plain\" hidden></div>\n      <div id=\"r-confirm\" class=\"callout bad\" hidden>This replaces the signing key on this device. <div class=\"row\" style=\"margin-top:8px\"><button class=\"btn danger solid sm\" type=\"button\" id=\"b-rc-yes\">Replace</button><button class=\"btn sm\" type=\"button\" id=\"b-rc-no\">Cancel</button></div></div>\n    </div>\n    <div class=\"box\">\n      <h2>Dashboard setup (once)</h2>\n      <ol class=\"note\" style=\"padding-left:18px;margin:0;display:flex;flex-direction:column;gap:4px\">\n        <li>Sign up free at cloudflare.com → Workers &amp; Pages → Create Worker named <span class=\"mono\">pharmadesk-admin</span>.</li>\n        <li>Edit code → paste the <span class=\"mono\">worker.js</span> file from PharmaDesk → Deploy.</li>\n        <li>Storage → KV → create <span class=\"mono\">pharmadesk-shops</span>, then bind it to the Worker as <span class=\"mono\">SHOPS</span>.</li>\n        <li>Worker settings → Variables: <span class=\"mono\">PUBLIC_KEY</span> = your public key above, <span class=\"mono\">ADMIN_TOKEN</span> = a long password (Secret).</li>\n        <li>Open the Worker address in any browser (Mac, Windows or iPhone) — this same app opens there with your shops.</li>\n      </ol>\n    </div>\n  </section>\n</div>\n<div class=\"toast\" id=\"toast\" hidden></div>\n\n<script>\n(() => {\n  const $ = s => document.querySelector(s);\n  const store = {\n    get(k, d) { try { const v = localStorage.getItem('pdv.' + k); return v == null ? d : JSON.parse(v); } catch { return d; } },\n    set(k, v) { try { localStorage.setItem('pdv.' + k, JSON.stringify(v)); return true; } catch { return false; } },\n  };\n  let memKeys = null; // fallback when storage is blocked\n  const keys = () => store.get('keys', null) || memKeys;\n  const esc = s => String(s ?? '').replace(/[&<>\"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]));\n  let tt; const toast = m => { const t = $('#toast'); t.textContent = m; t.hidden = false; clearTimeout(tt); tt = setTimeout(() => t.hidden = true, 2200); };\n  const copy = async (text, el) => { try { await navigator.clipboard.writeText(text); toast('Copied'); } catch { if (el) { const r = document.createRange(); r.selectNodeContents(el); const s = getSelection(); s.removeAllRanges(); s.addRange(r); } toast('Selected — press Copy'); } };\n\n  // ---------- base64 helpers ----------\n  const b64u = bytes => btoa(String.fromCharCode(...bytes)).replace(/\\+/g, '-').replace(/\\//g, '_').replace(/=+$/, '');\n  const b64 = bytes => btoa(String.fromCharCode(...bytes));\n  const unb64 = s => { s = s.replace(/-/g, '+').replace(/_/g, '/'); s += '==='.slice((s.length + 3) % 4); return Uint8Array.from(atob(s), c => c.charCodeAt(0)); };\n  const utf8b64u = str => b64u(new TextEncoder().encode(str));\n  const PKCS8_PREFIX = Uint8Array.from([0x30,0x2e,0x02,0x01,0x00,0x30,0x05,0x06,0x03,0x2b,0x65,0x70,0x04,0x22,0x04,0x20]);\n\n  // ---------- Ed25519 (browser built-in; library fallback for older browsers) ----------\n  let noble = null;\n  async function lib() { if (!noble) noble = await import('https://cdn.jsdelivr.net/npm/@noble/ed25519@2.1.0/+esm'); return noble; }\n  async function generate() {\n    try {\n      const kp = await crypto.subtle.generateKey({ name: 'Ed25519' }, true, ['sign', 'verify']);\n      const pub = new Uint8Array(await crypto.subtle.exportKey('raw', kp.publicKey));\n      const pk8 = new Uint8Array(await crypto.subtle.exportKey('pkcs8', kp.privateKey));\n      return { publicKey: b64u(pub), privatePkcs8: b64(pk8) };\n    } catch {\n      const n = await lib(); const seed = crypto.getRandomValues(new Uint8Array(32));\n      const pub = await n.getPublicKeyAsync(seed);\n      const pk8 = new Uint8Array(48); pk8.set(PKCS8_PREFIX); pk8.set(seed, 16);\n      return { publicKey: b64u(pub), privatePkcs8: b64(pk8) };\n    }\n  }\n  async function sign(k, msg) {\n    const data = new TextEncoder().encode(msg); const pk8 = unb64(k.privatePkcs8);\n    try {\n      const key = await crypto.subtle.importKey('pkcs8', pk8, { name: 'Ed25519' }, false, ['sign']);\n      return new Uint8Array(await crypto.subtle.sign({ name: 'Ed25519' }, key, data));\n    } catch { const n = await lib(); return await n.signAsync(data, pk8.slice(16)); }\n  }\n  async function verify(pubB64u, msg, sig) {\n    try { const key = await crypto.subtle.importKey('raw', unb64(pubB64u), { name: 'Ed25519' }, false, ['verify']); return await crypto.subtle.verify({ name: 'Ed25519' }, key, sig, new TextEncoder().encode(msg)); }\n    catch { const n = await lib(); return await n.verifyAsync(sig, new TextEncoder().encode(msg), unb64(pubB64u)); }\n  }\n\n  // ---------- tabs ----------\n  const show = tab => {\n    for (const b of document.querySelectorAll('.tab')) b.setAttribute('aria-selected', String(b.dataset.tab === tab));\n    for (const p of ['keys', 'shops', 'setup']) $('#p-' + p).hidden = p !== tab;\n    store.set('tab', tab);\n  };\n  document.querySelectorAll('.tab').forEach(b => b.onclick = () => show(b.dataset.tab));\n\n  // ---------- setup ----------\n  const isoDay = d => d.toISOString().slice(0, 10);\n  function renderKey() {\n    const k = keys();\n    $('#k-none').hidden = !!k; $('#k-have').hidden = !k; $('#nokey').hidden = !!k; $('#b-issue').disabled = !k;\n    if (k) { $('#k-pub').textContent = k.publicKey; $('#k-made').textContent = k.created ? 'Created ' + new Date(k.created).toLocaleDateString() : ''; }\n  }\n  $('#b-gen').onclick = async () => {\n    const k = { ...(await generate()), created: new Date().toISOString() };\n    if (!store.set('keys', k)) memKeys = k;\n    renderKey(); toast('Signing key created — copy your backup now');\n    $('#b-msg').textContent = 'Back up your new key now.';\n  };\n  $('#b-copypub').onclick = () => copy(keys().publicKey, $('#k-pub'));\n  $('#b-backup').onclick = () => { const k = keys(); if (!k) return toast('No key yet'); copy(JSON.stringify(k), null); $('#r-text').value = JSON.stringify(k); $('#b-msg').textContent = 'Backup copied. Also shown in the box below.'; };\n  let pending = null;\n  async function tryRestore(text) {\n    let k; try { k = JSON.parse(text.trim()); } catch { return toast('That is not a PharmaDesk backup'); }\n    if (!k || typeof k.publicKey !== 'string' || typeof k.privatePkcs8 !== 'string') return toast('That is not a PharmaDesk backup');\n    try { const t = 'check'; if (!(await verify(k.publicKey, t, await sign(k, t)))) throw 0; } catch { return toast('This backup is damaged'); }\n    if (keys() && keys().publicKey !== k.publicKey) { pending = k; $('#r-confirm').hidden = false; return; }\n    save(k);\n  }\n  function save(k) { if (!store.set('keys', k)) memKeys = k; renderKey(); toast('Signing key restored'); $('#r-confirm').hidden = true; }\n  $('#b-restore').onclick = () => tryRestore($('#r-text').value);\n  $('#r-file').onchange = async e => { const f = e.target.files[0]; if (f) tryRestore(await f.text()); e.target.value = ''; };\n  $('#b-rc-yes').onclick = () => { if (pending) save(pending); pending = null; };\n  $('#b-rc-no').onclick = () => { pending = null; $('#r-confirm').hidden = true; };\n\n  // ---------- issue ----------\n  const expiryText = () => { const d = +$('#i-days').value; $('#i-exp').textContent = d ? 'Expires ' + new Date(Date.now() + d * 864e5).toLocaleDateString(undefined, { day: 'numeric', month: 'long', year: 'numeric' }) : 'Never expires'; };\n  $('#i-days').onchange = expiryText; expiryText();\n  $('#i-plan').onchange = () => { if ($('#i-plan').value === 'trial') $('#i-days').value = '14'; expiryText(); };\n  $('#issue').onsubmit = async e => {\n    e.preventDefault(); const k = keys(); if (!k) return show('setup');\n    const shop = $('#i-shop').value.trim(); if (!shop) return;\n    const days = +$('#i-days').value;\n    const id = 'L-' + Array.from(crypto.getRandomValues(new Uint8Array(5)), b => b.toString(16).padStart(2, '0')).join('').toUpperCase();\n    const payload = { id, shop: shop.slice(0, 80), issued: isoDay(new Date()), expires: days ? isoDay(new Date(Date.now() + days * 864e5)) : null, plan: $('#i-plan').value, machine: $('#i-machine').value.trim() || null };\n    const body = utf8b64u(JSON.stringify(payload));\n    const token = `PD1.${body}.${b64u(await sign(k, body))}`;\n    $('#r-key').textContent = token; $('#r-title').textContent = 'Key for ' + payload.shop; $('#result').hidden = false;\n    const h = store.get('history', []); h.unshift({ ...payload, token }); store.set('history', h.slice(0, 500));\n    renderHist(); $('#result').scrollIntoView({ behavior: 'smooth', block: 'nearest' });\n  };\n  $('#b-copykey').onclick = () => copy($('#r-key').textContent, $('#r-key'));\n  function renderHist() {\n    const q = $('#h-q').value.toLowerCase(); const h = store.get('history', []).filter(x => !q || x.shop.toLowerCase().includes(q) || x.id.toLowerCase().includes(q));\n    $('#h-empty').hidden = h.length > 0;\n    $('#hist').innerHTML = h.map((x, i) => `<tr><td><b>${esc(x.shop)}</b><div class=\"mono\" style=\"color:var(--muted)\">${esc(x.id)}</div></td><td>${esc(x.plan)}</td><td>${esc(x.issued)}</td><td>${x.expires ? esc(x.expires) + ' ' + expPill(x.expires) : '<span class=\"pill plain\">Never</span>'}</td><td><button class=\"btn sm\" data-copy=\"${i}\" type=\"button\">Copy key</button></td></tr>`).join('');\n    $('#hist').querySelectorAll('[data-copy]').forEach(b => b.onclick = () => copy(h[+b.dataset.copy].token, null));\n  }\n  $('#h-q').oninput = renderHist;\n  const daysLeft = iso => Math.ceil((Date.parse(iso + 'T23:59:59') - Date.now()) / 864e5);\n  const expPill = iso => { const d = daysLeft(iso); return d < 0 ? '<span class=\"pill bad\">Expired</span>' : d <= 30 ? `<span class=\"pill warn\">${d} days left</span>` : ''; };\n\n  // ---------- shops ----------\n  const onWorker = !!window.PD_WORKER;\n  if (onWorker) $('#l-api').hidden = true;\n  $('#c-api').value = store.get('api', ''); $('#c-tok').value = store.get('tok', '');\n  const api = () => onWorker ? location.origin : $('#c-api').value.trim().replace(/\\/$/, '');\n  let shops = null, example = false;\n  async function call(path, opts = {}) {\n    const r = await fetch(api() + path, { ...opts, headers: { 'content-type': 'application/json', authorization: 'Bearer ' + $('#c-tok').value } });\n    const d = await r.json().catch(() => ({}));\n    if (!r.ok) throw new Error(d.error || 'The dashboard answered ' + r.status);\n    return d;\n  }\n  async function load() {\n    $('#c-msg').textContent = 'Loading…';\n    try { shops = (await call('/shops')).shops; example = false; $('#c-msg').textContent = `Updated ${new Date().toLocaleTimeString()}`; store.set('api', $('#c-api').value.trim()); store.set('tok', $('#c-tok').value); }\n    catch (e) { $('#c-msg').textContent = /fetch|network|load/i.test(e.message) ? 'Could not reach the dashboard. Check the address — or open the dashboard address itself in your browser.' : e.message; return; }\n    renderShops();\n  }\n  $('#conn').onsubmit = e => { e.preventDefault(); if (!api()) { $('#c-msg').textContent = 'Enter your dashboard address'; return; } load(); };\n  const ago = iso => { const m = (Date.now() - Date.parse(iso)) / 6e4; return m < 2 ? 'just now' : m < 60 ? Math.round(m) + ' min ago' : m < 1440 ? Math.round(m / 60) + ' h ago' : Math.round(m / 1440) + ' days ago'; };\n  const rs = p => 'Rs ' + Math.round((p || 0) / 100).toLocaleString('en-PK');\n  const state = s => s.suspended ? 'paused' : (Date.now() - Date.parse(s.lastSeen)) > 3 * 864e5 ? 'stale' : 'active';\n  function renderShops() {\n    const list = shops || [];\n    const act = list.filter(s => state(s) === 'active').length, paused = list.filter(s => s.suspended).length, exp = list.filter(s => s.expires && daysLeft(s.expires) <= 30).length;\n    const sales = list.reduce((a, s) => a + ((s.stats || {}).sales7d || 0), 0);\n    $('#tiles').innerHTML = [['Shops', list.length], ['Active', act], ['Paused', paused], ['Expiring ≤ 30 days', exp], ['Sales, 7 days (all)', rs(sales)]].map(([l, v]) => `<div class=\"tile\"><span>${l}</span><b>${v}</b></div>`).join('');\n    $('#s-ex').hidden = !example;\n    const q = $('#s-q').value.toLowerCase(), f = $('#s-f').value;\n    const shown = list.filter(s => (!q || [s.shop, s.licensedTo, s.city, s.phone].join(' ').toLowerCase().includes(q))\n      && (f === 'all' || (f === 'active' && state(s) === 'active') || (f === 'paused' && s.suspended) || (f === 'stale' && state(s) === 'stale') || (f === 'expiring' && s.expires && daysLeft(s.expires) <= 30) || (f === 'support' && s.support)))\n      .sort((a, b) => Date.parse(b.lastSeen) - Date.parse(a.lastSeen));\n    $('#shops').innerHTML = shown.length ? shown.map(card).join('') : `<div class=\"box\"><p class=\"note\">${list.length ? 'No shops match.' : 'No shops yet. A shop appears here once it is activated with your key and has internet.'}</p></div>`;\n    $('#shops').querySelectorAll('[data-act]').forEach(b => b.onclick = () => act2(b.dataset.id, b.dataset.act, b));\n  }\n  function card(s) {\n    const st = state(s), x = s.stats || {};\n    const pill = st === 'paused' ? '<span class=\"pill bad\">Paused</span>' : st === 'stale' ? '<span class=\"pill warn\">Not seen 3+ days</span>' : '<span class=\"pill good\">Active</span>';\n    const sup = s.support ? `<div class=\"support\"><b>Support access is ON (owner allowed it)</b>\n      <div>Address: <span class=\"mono\">${esc(s.support.url || 'shop Wi-Fi only')}</span></div>\n      <div>Login: <span class=\"mono\">${esc(s.support.username)}</span> · PIN <span class=\"mono\">${esc(s.support.pin)}</span></div>\n      <div>Server PIN: <span class=\"mono\">${esc(s.support.serverPin)}</span> <button class=\"btn sm\" type=\"button\" data-act=\"pair\" data-id=\"${esc(s.installId)}\">Copy pairing code</button></div></div>` : '';\n    return `<article class=\"shop ${st}\">\n      <div class=\"row\"><h3>${esc(s.shop || s.licensedTo)}</h3><span class=\"spacer\"></span>${pill}</div>\n      <dl><dt>Licensed to</dt><dd>${esc(s.licensedTo)} · ${esc(s.plan)}</dd>\n      <dt>Expires</dt><dd>${s.expires ? esc(s.expires) + ' ' + expPill(s.expires) : 'Never'}</dd>\n      <dt>Phone</dt><dd>${esc(s.phone || '—')}</dd><dt>Address</dt><dd>${esc(s.city || '—')}</dd>\n      <dt>Last seen</dt><dd>${ago(s.lastSeen)} · v${esc(s.version)} · ${esc(s.platform === 'win32' ? 'Windows' : s.platform === 'darwin' ? 'Mac' : s.platform)}</dd></dl>\n      <div class=\"stats\"><div class=\"stat\"><b>${x.bills7d ?? 0}</b>bills 7d</div><div class=\"stat\"><b>${rs(x.sales7d)}</b>sales 7d</div><div class=\"stat\"><b>${x.medicines ?? 0}</b>medicines</div><div class=\"stat\"><b>${x.users ?? 0}</b>users</div><div class=\"stat\"><b>${x.devices ?? 0}</b>phones/PCs</div><div class=\"stat\"><b>${x.patients ?? 0}</b>customers</div></div>\n      ${s.suspended && s.note ? `<div class=\"note\">Message to shop: ${esc(s.note)}</div>` : ''}\n      ${sup}\n      <div class=\"row\" data-box=\"${esc(s.installId)}\">\n        ${s.suspended ? `<button class=\"btn primary sm\" type=\"button\" data-act=\"resume\" data-id=\"${esc(s.installId)}\">Resume</button>` : `<button class=\"btn danger sm\" type=\"button\" data-act=\"pause\" data-id=\"${esc(s.installId)}\">Pause billing</button>`}\n        <span class=\"spacer\"></span><button class=\"btn sm\" type=\"button\" data-act=\"forget\" data-id=\"${esc(s.installId)}\">Remove from list</button>\n      </div></article>`;\n  }\n  async function act2(id, act, btn) {\n    const s = (shops || []).find(x => x.installId === id); if (!s) return;\n    const box = btn.closest('[data-box]') || btn.parentElement;\n    if (act === 'pair') { const p = s.support || {}; return copy(p.pairCode || '', null); }\n    if (example) return toast('Example shop — connect your dashboard first');\n    if (act === 'pause') {\n      box.innerHTML = `<input placeholder=\"Message the shop will see (e.g. Plan expired — please renew)\" maxlength=\"200\" style=\"flex:1 1 220px\"><button class=\"btn danger solid sm\" type=\"button\">Pause</button><button class=\"btn sm\" type=\"button\">Cancel</button>`;\n      const [inp, yes, no] = box.children; inp.focus();\n      no.onclick = renderShops;\n      yes.onclick = async () => { try { await call(`/shops/${id}/suspend`, { method: 'POST', body: JSON.stringify({ on: true, note: inp.value || 'Your plan is paused. Please contact Awais Amin: awaisdpw.co@gmail.com' }) }); s.suspended = true; s.note = inp.value; toast('Paused — takes effect at the shop\\'s next check-in'); } catch (e) { toast(e.message); } renderShops(); };\n      return;\n    }\n    if (act === 'forget') {\n      box.innerHTML = `<span class=\"note\" style=\"flex:1\">Remove ${esc(s.shop)} from the list? It comes back if it checks in again.</span><button class=\"btn danger solid sm\" type=\"button\">Remove</button><button class=\"btn sm\" type=\"button\">Cancel</button>`;\n      const [, yes, no] = box.children; no.onclick = renderShops;\n      yes.onclick = async () => { try { await call(`/shops/${id}/forget`, { method: 'POST', body: '{}' }); shops = shops.filter(x => x.installId !== id); toast('Removed'); } catch (e) { toast(e.message); } renderShops(); };\n      return;\n    }\n    if (act === 'resume') { try { await call(`/shops/${id}/suspend`, { method: 'POST', body: JSON.stringify({ on: false }) }); s.suspended = false; s.note = ''; toast('Resumed'); } catch (e) { toast(e.message); } renderShops(); }\n  }\n  $('#s-q').oninput = renderShops; $('#s-f').onchange = renderShops;\n\n  // Example shops so the screen shows what it does before you connect.\n  const now = Date.now(), iso = ms => new Date(ms).toISOString();\n  shops = [\n    { installId: 'ex1', shop: 'Al-Shifa Pharmacy', licensedTo: 'Al-Shifa Pharmacy', plan: 'standard', expires: isoDay(new Date(now + 200 * 864e5)), phone: '0300-1234567', city: 'Main Bazar, Okara', version: '1.0.0', platform: 'win32', lastSeen: iso(now - 40 * 6e4), stats: { bills7d: 412, sales7d: 18650000, medicines: 1240, users: 4, devices: 3, patients: 380 }, suspended: false, support: null },\n    { installId: 'ex2', shop: 'City Care Chemist', licensedTo: 'City Care Chemist', plan: 'trial', expires: isoDay(new Date(now + 6 * 864e5)), phone: '0321-7654321', city: 'Lahore', version: '1.0.0', platform: 'darwin', lastSeen: iso(now - 5 * 36e5), stats: { bills7d: 96, sales7d: 3120000, medicines: 520, users: 2, devices: 1, patients: 64 }, suspended: false, support: { username: 'vendor-support', pin: '48213907', serverPin: '552901', url: 'https://example.trycloudflare.com', pairCode: 'pharmadesk:example' } },\n  ];\n  example = true;\n\n  // ---------- start ----------\n  renderKey(); renderHist(); renderShops();\n  show(store.get('tab', onWorker ? 'shops' : 'keys'));\n  if ($('#c-tok').value && (onWorker || $('#c-api').value)) load();\n})();\n</script>\n</body></html>";
const ICONS = {"/icon-192.png":"","/icon-512.png":""};
const MANIFEST = "{\"name\":\"PharmaDesk Vendor\",\"short_name\":\"PD Vendor\",\"id\":\"/\",\"start_url\":\"/\",\"scope\":\"/\",\"display\":\"standalone\",\"background_color\":\"#0A1413\",\"theme_color\":\"#0E8F7E\",\"icons\":[{\"src\":\"/icon-192.png\",\"sizes\":\"192x192\",\"type\":\"image/png\",\"purpose\":\"any\"},{\"src\":\"/icon-512.png\",\"sizes\":\"512x512\",\"type\":\"image/png\",\"purpose\":\"any\"}]}";
const SW = "self.addEventListener('install',e=>self.skipWaiting());self.addEventListener('activate',e=>e.waitUntil(self.clients.claim()));self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(e.request.method!=='GET'||u.origin!==location.origin||u.pathname.startsWith('/shops'))return;e.respondWith(fetch(e.request).then(r=>{const c=r.clone();caches.open('pdv').then(x=>x.put(e.request,c));return r}).catch(()=>caches.match(e.request)))});";
